local a={}a.__index=a;local b=require("core.log")function a.new()return setmetatable({observers={},observerOrder={},sequence=0},a)end;function a:subscribe(c,d)assert(type(c)=="string"and c~="","Observer name is required")assert(type(d)=="function","Observer callback must be a function")assert(not self.observers[c],"Duplicate snapshot observer: "..c)self.observers[c]=d;self.observerOrder[#self.observerOrder+1]=c;return function()self.observers[c]=nil;for e,f in ipairs(self.observerOrder)do if f==c then table.remove(self.observerOrder,e)break end end end end;function a:publish(g)assert(type(g)=="table","Snapshot must be a table")self.sequence=self.sequence+1;g.sequence=self.sequence;for h,c in ipairs(self.observerOrder)do local d=self.observers[c]if d then local i,j=pcall(d,g)if not i then if tostring(j)=="Terminated"then error(j,0)end;b.write("ERROR","snapshot_bus","Observer ["..c.."]: "..tostring(j))print("Snapshot-Observer-Fehler ["..c.."]: "..tostring(j))end end end end;return a
